import{_ as n,l,o as e,c as o,v as t,p as s,x as r,d as m,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"方差互换与 VIX","description":"","frontmatter":{"title":"方差互换与 VIX","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/variance-swap-vix.md","filePath":"quant/variance-swap-vix.md","lastUpdated":1789023840000}'),p={name:"quant/variance-swap-vix.md"};function E(B,a,c,V,A,I){const i=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="方差互换与-vix" tabindex="-1">方差互换与 VIX <a class="header-anchor" href="#方差互换与-vix" aria-label="Permalink to &quot;方差互换与 VIX&quot;">​</a></h1><div class="epigraph"><p>对数合约可由香草期权的连续条带复制；因此已实现方差的公平价格不依赖波动率模型，只依赖可观测的欧式价格。</p><footer>—— Carr and Madan, Towards a Theory of Volatility Trading, 1998；CBOE VIX 方法说明书</footer></div><p><a href="/quant/sabr">上一课</a>用 \\(\\alpha,\\beta,\\rho,\\nu\\) 标记单一到期的微笑，交付物是 Black/Bachelier 隐含波动的奇异摄动近似，便于插值，而不是特征函数。缺口是「交易波动率」若只停留在切片插值，标的仍混着 Delta 与执行价选择：方差互换把已实现方差做成可复制合同，VIX 把 30 天隐含方差做成可观测指数。Carr–Madan 与 Demeterfi 等人说明对数合约条带能去掉模型依赖的公平方差执行价。本课写复制与指数规则，不重写 SABR 的 \\(\\beta\\)–\\(\\rho\\) 辨识。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SABR 把单一到期的微笑写成可插值的 \\(\\sigma_{\\mathrm{imp}}\\)。交易「波动率」若只买卖 ATM 期权，希腊字母会混进 Delta、Gamma、Theta，执行价选择还暗含模型。若能直接交换已实现方差，标的就变成二次变差，对冲应落在对数合约上：Itô 公式把 \\((\\mathrm{d}S/S)^2\\) 与 \\(\\mathrm{d}\\ln S\\) 连起来，剩余的是边界项与跳跃。连续路径下，方差的风险中性期望等于对数合约的价格，而 Carr–Madan 的跨执行价积分把任意两次可微收益写成香草条带。于是问题变成：市场是否提供足够密的看涨看跌，以及离散执行价、跳跃、股息、利率如何修正理想公式。</p><p>VIX 要解决的是另一侧的可观测性：把「30 天隐含方差」做成实时指数，供期货与期权挂靠。它必须用有限的上市执行价、两个到期、以及公开的报价规则，去逼近连续条带与连续到期。指数是复制组合的价格（再开方、年化），不是历史已实现波动，也不是 Heston 或 SABR 的参数。</p><h3 id="对数合约与二次变差" tabindex="-1">对数合约与二次变差 <a class="header-anchor" href="#对数合约与二次变差" aria-label="Permalink to &quot;对数合约与二次变差&quot;">​</a></h3><p>对扩散 \\(\\mathrm{d}S=\\mu S\\mathrm{d}t+\\sigma S\\mathrm{d}W\\)，Itô 给出</p> \\[\\mathrm{d}\\ln S = \\frac{\\mathrm{d}S}{S} - \\frac12 \\sigma^2\\mathrm{d}t, \\]<p>积分并取期望，已实现方差 \\(\\int_0^T\\sigma_t^2\\mathrm{d}t\\) 的公平值由 \\(\\mathbb{E}[\\ln(S_T/F)]\\) 与可交易的期货滚动决定。跳跃会留下与跳跃大小有关的额外项，复制不再完美，方差互换相对波动率互换（对 \\(\\sigma\\) 而不是 \\(\\sigma^2\\) 结算）的凸性也来自 Jensen。Carr–Madan 强调的是收益的静态复制：与路径无关的欧式收益，可用 \\(\\int \\mathrm{OTM}/K^2\\,\\mathrm{d}K\\) 合成。</p><p><span class="marginnote">方差互换的执行价报价常写成「波动率点」：公平方差开方后再年化。合同结算的是方差，不是波动率；用波动率点只是习惯。把 VIX 期货当成「已实现波动的预测」而不看方差凸性，会算错期望。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>连续执行价下，公平方差执行价（适当年化）形如</p> \\[\\frac{2}{T}\\mathrm{e}^{rT}\\left(\\int_0^{F}\\frac{P(K)}{K^2}\\,\\mathrm{d}K+\\int_F^{\\infty}\\frac{C(K)}{K^2}\\,\\mathrm{d}K\\right) \\]<p>的离散或带利率修正版本，其中 \\(P,C\\) 为欧式看跌与看涨，\\(F\\) 为远期。实盘用有限的 \\(K_i\\)，权重 \\(1/K^2\\) 用梯形或 CBOE 的 \\(\\Delta K/K^2\\)。OTM 一侧用看跌、另一侧用看涨，是为了用更宽的流动性，并在平值附近衔接。</p><p>CBOE VIX 对近月与次近月的 S&amp;P 500 期权分别做上述离散和，得到两个方差，再线性插值到 30 天，最后开方乘 100。排除权价过低的执行价，选用中间价，并规定买卖价差与不可用报价的过滤。指数以「波动率点」显示，对应方差互换公平值的平方根，不是该方差互换本身的交易价格——交易的是 VIX 期货、期权与 OTC 方差互换，指数只是复制公式的公开计算。</p><h3 id="从条带到-vix-期货" tabindex="-1">从条带到 VIX 期货 <a class="header-anchor" href="#从条带到-vix-期货" aria-label="Permalink to &quot;从条带到 VIX 期货&quot;">​</a></h3><p>方差互换 OTC 合约直接对已实现方差结算，对冲是持有对数条带并 Delta 对冲标的。VIX 期货是对未来某一时刻 VIX 指数的期货，而 VIX 指数本身已是期权条带；因此 VIX 期货的标的是「未来的 30 天香草条带」，不是现货指数的已实现方差。期限结构可以升水或贴水，反映方差的风险溢价与均值回复。用现货 VIX 去对冲 VIX 期货会留下基差：复制组合的成分期权与期货到期并不相同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(1/K^2\\) 权重来自对数收益对执行价的二阶导。虚值看跌（低 \\(K\\)）权重大，故左翼流动性与跳风险对公平方差极敏感：缺了低执行价，VIX 会被低估。这与微笑管理一致——偏斜越陡，方差互换越贵，ATM 波动不能代表公平方差。Heston 里公平方差可由方差过程的期望直接积分，但那是模型内的数；市场方差互换价格应由条带给出，再用模型去解释风险溢价。</p><p>离散采样的已实现方差（日对数收益平方和）与连续二次变差有差别；合同会规定观测频率、开盘开盘还是收盘收盘、是否包含隔夜。复制论证对应连续路径与连续对冲；离散对冲误差与跳跃使 OTC 做市必须加价。VIX 用期权市场价格，已经把风险溢价含进指数：VIX 通常高于事后已实现波动，这是方差风险溢价的现象，不是计算 bug。</p><h3 id="与隐含波动率曲面的关系" tabindex="-1">与隐含波动率曲面的关系 <a class="header-anchor" href="#与隐含波动率曲面的关系" aria-label="Permalink to &quot;与隐含波动率曲面的关系&quot;">​</a></h3><p>每个执行价的 Black 隐含波动进入的是期权价格，再经 \\(1/K^2\\) 积分。因此 VIX 是微笑的积分变换，不是 ATM 点。SABR 或 Heston 校准若只拟合 ATM 与 25Delta，可能仍错方差互换，因为翼部积分权重大。反过来，方差互换是检查曲面无套利与翼部质量的诊断：条带积分若对新增远翼执行价极度敏感，说明外推不稳。</p><p><span class="marginnote">2003 年前的旧 VIX（常称 VXO）基于 S&amp;P 100 与 Black 公式的隐含波动平均，与现行 VIX 不可混用。论文与时间序列若跨越修订，必须声明口径。</span></p>',24)),(e(),s(h,null,{default:r(()=>[d(i,{id:"mermaid-66",class:"mermaid",graph:"flowchart%20TD%0A%20%20Van%5B%22OTM%20%E9%A6%99%E8%8D%89%E6%9D%A1%E5%B8%A6%22%5D%20--%3E%20Log%5B%22%E5%90%88%E6%88%90%E5%AF%B9%E6%95%B0%E5%90%88%E7%BA%A6%22%5D%0A%20%20Log%20--%3E%20VS%5B%22%E6%96%B9%E5%B7%AE%E4%BA%92%E6%8D%A2%E5%85%AC%E5%B9%B3%E6%89%A7%E8%A1%8C%E4%BB%B7%22%5D%0A%20%20Real%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%96%B9%E5%B7%AE%22%5D%20--%3E%20Settle%5B%22%E5%88%B0%E6%9C%9F%E7%BB%93%E7%AE%97%E5%B7%AE%E9%A2%9D%22%5D%0A%20%20VS%20--%3E%20Settle%0A%20%20Van%20--%3E%20VIX%5B%22CBOE%20VIX%20%E7%A6%BB%E6%95%A3%E5%85%AC%E5%BC%8F%22%5D%0A%20%20VIX%20--%3E%20Fut%5B%22VIX%20%E6%9C%9F%E8%B4%A7%20%2F%20%E6%9C%9F%E6%9D%83%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>复制假设欧式、连续 \\(K\\)、连续交易、有限跳跃或纯扩散。美式提前行权、离散股息、停牌、相关交易所的报价不同步，都会造成条带误差。CBOE 规则是指数定义，不是 OTC 合同条款；SPX 周期权与标准月期权的纳入规则会变，历史序列要按当时说明书复原。开方把方差变成波动率，Jensen 使「期望 VIX」不等于「期望已实现波动」。</p><p>方差互换对单名股票还有借券、股息与跳跃风险，流动性远差于指数。VIX 只锚定 S&amp;P 500。Carr–Madan（1998）给出波动率交易与香草复制的理论骨架；CBOE 说明书给出指数的操作定义；二者一起解释「为什么可以用期权条带来谈 30 天方差」，而不要把 VIX 理解成 Heston 的 \\(v_0\\) 或历史标准差。</p><p><span class="marginnote">把 VIX 当成「恐惧指数」只是叙事。数量上它是 30 天方差互换复制的平方根；叙事不能替代 \\(1/K^2\\) 积分与期货基差。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>连续路径下，已实现方差的公平价格由对数合约给出；Carr–Madan 用香草条带静态复制对数收益。</li><li>权重 \\(1/K^2\\) 使左翼看跌对公平方差极重要；ATM 隐含波动不是方差互换。</li><li>CBOE VIX 是 SPX 期权离散条带插值到 30 天再开方，贴近方差互换而不是旧式 Black ATM。</li><li>VIX 期货标的是未来的指数复制，与 OTC 方差互换、与已实现波动都有基差。</li><li>跳跃、离散对冲、有限执行价使复制不完美，构成出价。</li><li>出处：Carr and Madan, 1998；Demeterfi, Derman, Kamal, Zou, 1999；CBOE <em>VIX White Paper</em>；产品语境见 Hull。</li></ul>',6))])}const X=n(p,[["render",E]]);export{u as __pageData,X as default};
